[{"order":1,"type":"heading","text":"Password Hashing in PHP with password_hash and password_verify"},{"order":2,"type":"paragraph","text":"This tutorial explains how to securely store user passwords in a database using PHP's built-in password hashing functions: `password_hash()` and `password_verify()`. These functions provide a robust and secure way to protect user credentials against common attacks."},{"order":3,"type":"subheading","text":"Why Password Hashing is Important"},{"order":4,"type":"paragraph","text":"Storing passwords in plain text is extremely dangerous. If your database is compromised, attackers will have direct access to all user passwords. Hashing transforms passwords into a one-way string of characters, making it computationally infeasible to reverse the process and obtain the original password. Salting adds a unique, random string to each password before hashing, further increasing security by preventing rainbow table attacks."},{"order":5,"type":"subheading","text":"Using password_hash()"},{"order":6,"type":"paragraph","text":"The `password_hash()` function creates a new password hash using a strong one-way hashing algorithm. It automatically handles salting and ensures that the generated hash is secure."},{"order":7,"type":"code","text":"&lt;?php
$password = 'MySecretPassword123';

// Hash the password using the default algorithm (BCRYPT)
$hashedPassword = password_hash($password, PASSWORD_DEFAULT);

echo "Hashed password: " . $hashedPassword . "\n";

// You can also specify a specific algorithm and options
$options = [
    'cost' => 12, // Adjust the cost factor for more security (higher = slower)
];
$hashedPasswordWithOptions = password_hash($password, PASSWORD_BCRYPT, $options);

echo "Hashed password with options: " . $hashedPasswordWithOptions . "\n";
?&gt;"},{"order":8,"type":"bullet_point","text":"`PASSWORD_DEFAULT`: Uses the bcrypt algorithm (as of PHP 5.5.0). This algorithm is subject to change in future PHP versions to use newer, stronger algorithms. It's recommended to use this option for maximum compatibility and security."},{"order":9,"type":"bullet_point","text":"`PASSWORD_BCRYPT`:  Explicitly specifies the bcrypt algorithm. You can customize the cost factor using the 'cost' option. Higher cost factors increase security but also increase hashing time."},{"order":10,"type":"paragraph","text":"Important: Store the `$hashedPassword` in your database.  The `password_hash()` function generates a different hash each time, even for the same password, due to the random salt.  This is intentional and enhances security."},{"order":11,"type":"subheading","text":"Using password_verify()"},{"order":12,"type":"paragraph","text":"The `password_verify()` function verifies that a given password matches a hash. It automatically extracts the salt and algorithm information from the hash and performs the necessary comparisons."},{"order":13,"type":"code","text":"&lt;?php
$password = 'MySecretPassword123';
$hashedPassword = '$2y$10$someRandomSaltStringHere'; // Replace with the actual hashed password from your database

if (password_verify($password, $hashedPassword)) {
    echo 'Password is valid!';
} else {
    echo 'Invalid password.';
}
?&gt;"},{"order":14,"type":"paragraph","text":"Note: Replace `'$2y$10$someRandomSaltStringHere'` with the actual hashed password retrieved from your database."},{"order":15,"type":"subheading","text":"Example: User Registration and Login"},{"order":16,"type":"code","text":"&lt;?php
// Registration
function registerUser($username, $password, $db) {
    $hashedPassword = password_hash($password, PASSWORD_DEFAULT);
    // Store $username and $hashedPassword in your database
    $stmt = $db->prepare("INSERT INTO users (username, password) VALUES (?, ?)");
    $stmt->bind_param("ss", $username, $hashedPassword);
    $stmt->execute();
}

// Login
function loginUser($username, $password, $db) {
    $stmt = $db->prepare("SELECT password FROM users WHERE username = ?");
    $stmt->bind_param("s", $username);
    $stmt->execute();
    $result = $stmt->get_result();

    if ($result->num_rows > 0) {
        $row = $result->fetch_assoc();
        $hashedPassword = $row['password'];

        if (password_verify($password, $hashedPassword)) {
            // Password is correct, start a session or set a cookie
            echo "Login successful!";
            return true;
        } else {
            echo "Invalid password.";
            return false;
        }
    } else {
        echo "User not found.";
        return false;
    }
}

// Example Usage (replace with your actual database connection)
$db = new mysqli('localhost', 'username', 'password', 'database');

// Register a new user
registerUser('testuser', 'securePassword123', $db);

// Attempt to log in
loginUser('testuser', 'securePassword123', $db);

$db->close();
?&gt;"},{"order":17,"type":"subheading","text":"Important Considerations"},{"order":18,"type":"bullet_point","text":"Always use prepared statements to prevent SQL injection vulnerabilities when interacting with your database."},{"order":19,"type":"bullet_point","text":"Store the hashed passwords in a column with sufficient length (at least 255 characters) to accommodate the generated hashes."},{"order":20,"type":"bullet_point","text":"Regularly rehash passwords with a stronger algorithm or higher cost factor as technology evolves."},{"order":21,"type":"bullet_point","text":"Consider using a password strength meter to encourage users to create strong passwords."},{"order":22,"type":"subheading","text":"Conclusion"},{"order":23,"type":"paragraph","text":"`password_hash()` and `password_verify()` provide a simple and secure way to handle password storage in PHP. By following these best practices, you can significantly improve the security of your web applications and protect your users' credentials."}]
